const AbilitySchema = z
    .object({
    生命值: z.coerce.number().transform(v => _.clamp(v, 0, 9999)).prefault(100),
    攻击力: z.coerce.number().transform(v => _.clamp(v, 0, 999)).prefault(10),
    防御力: z.coerce.number().transform(v => _.clamp(v, 0, 999)).prefault(10),
    敏捷: z.coerce.number().transform(v => _.clamp(v, 0, 999)).prefault(10),
})
    .prefault({});
const NpcSchema = z
    .object({
    头像: z.string().prefault(''),
    性别: z.string().prefault('未知'),
    身份: z.string().prefault(''),
    等级: z.coerce.number().transform(v => _.clamp(v, 1, 100)).prefault(1),
    能力: AbilitySchema,
    外貌穿着: z.string().prefault(''),
    内心想法: z.string().prefault(''),
    位置: z.string().prefault('未知'),
    好感度: z.coerce.number().transform(v => _.clamp(v, 0, 100)).prefault(0),
    性经验: z.coerce.number().transform(v => _.clamp(v, 0, 100)).prefault(0),
    近期性经历: z.string().prefault(''),
})
    .prefault({});
const DEFAULT_TEST_NPC_DIRECTORY = {
    莉娅: {
        头像: '1ycr6y.png',
        性别: '女',
        身份: '测试角色',
        等级: 10,
        能力: { 生命值: 200, 攻击力: 28, 防御力: 22, 敏捷: 35 },
        外貌穿着: '轻便旅装，发色柔和',
        内心想法: '（测试数据）……',
        位置: '王城',
        好感度: 20,
        性经验: 0,
        近期性经历: '无',
    },
};
export { DEFAULT_TEST_NPC_DIRECTORY };
export const Schema = z
    .object({
    主角: z
        .object({
        头像: z.string().prefault(''),
        姓名: z.string().prefault('旅人'),
        性别: z.string().prefault('未知'),
        性格: z.string().prefault(''),
        外貌: z.string().prefault(''),
        身份: z.string().prefault('冒险者'),
        等级: z.coerce.number().transform(v => _.clamp(v, 1, 100)).prefault(1),
        能力: AbilitySchema,
    })
        .prefault({}),
    背包: z
        .record(z.string().describe('物品名'), z
        .object({
        描述: z.string().prefault(''),
        数量: z.coerce.number().prefault(1),
    })
        .prefault({}))
        .prefault({})
        .transform(data => _.pickBy(data, ({ 数量 }) => 数量 > 0)),
    邂逅名录: z
        .record(z.string().describe('NPC名'), NpcSchema)
        .prefault({})
        .transform(data => (_.isEmpty(data) ? DEFAULT_TEST_NPC_DIRECTORY : data)),
    已解锁CG: z.record(z.string().describe('角色名'), z.array(z.string()).prefault([])).prefault({}),
})
    .prefault({});
